package br.com.luvi.financaspessoais.dashboard.service;
import br.com.luvi.financaspessoais.conta.entity.ContaFinanceira; import br.com.luvi.financaspessoais.conta.service.ContaService; import br.com.luvi.financaspessoais.dashboard.dto.DashboardResponse; import br.com.luvi.financaspessoais.lancamento.entity.Lancamento; import br.com.luvi.financaspessoais.lancamento.enums.TipoLancamento; import br.com.luvi.financaspessoais.lancamento.repository.LancamentoRepository; import br.com.luvi.financaspessoais.usuario.entity.Usuario; import org.springframework.stereotype.Service; import java.math.BigDecimal; import java.time.*; import java.time.format.TextStyle; import java.util.*;
@Service public class DashboardService{private final LancamentoRepository repo;private final ContaService contas;public DashboardService(LancamentoRepository r,ContaService c){repo=r;contas=c;} private List<Long> ids(Usuario u,Long contaId,Long grupoId){if(contaId!=null){if(!contas.podeAcessar(contaId,u))throw new SecurityException("Conta não permitida.");return List.of(contaId);}if(grupoId!=null)return contas.doGrupo(grupoId,u).stream().map(ContaFinanceira::getId).toList();return contas.acessiveis(u).stream().map(ContaFinanceira::getId).toList();}
 public DashboardResponse obter(int mes,int ano,Long contaId,Long grupoId,Usuario u){var ids=ids(u,contaId,grupoId);if(ids.isEmpty())return new DashboardResponse(BigDecimal.ZERO,BigDecimal.ZERO,BigDecimal.ZERO,List.of(),List.of());YearMonth ym=YearMonth.of(ano,mes);var atual=repo.findByContaIdInAndDataBetweenOrderByDataDescDataHoraCadastroDescIdDesc(ids,ym.atDay(1),ym.atEndOfMonth());BigDecimal rec=soma(atual,TipoLancamento.RECEITA),des=soma(atual,TipoLancamento.DESPESA);Map<String,BigDecimal> mapa=new HashMap<>();atual.stream().filter(x->x.getTipo()==TipoLancamento.DESPESA).forEach(x->mapa.merge(x.getCategoria().getNome(),x.getValor(),BigDecimal::add));var cats=mapa.entrySet().stream().sorted(Map.Entry.<String,BigDecimal>comparingByValue().reversed()).map(e->new DashboardResponse.CategoriaTotal(e.getKey(),e.getValue())).toList();List<DashboardResponse.MesTotal> ev=new ArrayList<>();for(int i=5;i>=0;i--){YearMonth m=ym.minusMonths(i);var ls=repo.findByContaIdInAndDataBetweenOrderByDataDescDataHoraCadastroDescIdDesc(ids,m.atDay(1),m.atEndOfMonth());String nome=m.getMonth().getDisplayName(TextStyle.SHORT,new Locale("pt","BR"))+"/"+String.valueOf(m.getYear()).substring(2);ev.add(new DashboardResponse.MesTotal(nome,soma(ls,TipoLancamento.RECEITA),soma(ls,TipoLancamento.DESPESA)));}return new DashboardResponse(rec,des,rec.subtract(des),cats,ev);}private BigDecimal soma(List<Lancamento>ls,TipoLancamento t){return ls.stream().filter(x->x.getTipo()==t).map(Lancamento::getValor).reduce(BigDecimal.ZERO,BigDecimal::add);}}
